import{_ as a,o as r,c as t,a2 as l}from"./chunks/framework.DfDAiEgj.js";const u=JSON.parse('{"title":"工具","description":"","frontmatter":{},"headers":[],"relativePath":"skill/tools.md","filePath":"skill/tools.md","lastUpdated":null}'),i={name:"skill/tools.md"};function o(p,e,s,n,c,h){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h1><p>工具只是工具，没有绝对的标准、只要适合就好</p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><ul><li><a href="https://www.iamxiarui.com/?paged=3&amp;cat=111" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?paged=3&amp;cat=111</a></li><li><a href="https://blog.csdn.net/liwei16611/article/details/100106262##" target="_blank" rel="noreferrer">https://blog.csdn.net/liwei16611/article/details/100106262##</a> UML</li></ul><p><a href="https://www.iamxiarui.com/?p=1231" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?p=1231</a></p><h2 id="axure-1" tabindex="-1">Axure <a href="https://www.yinxiang.com/everhub/note/435c8b2c-9127-43f3-a6e3-fc5f8898d893" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#axure-1" aria-label="Permalink to &quot;Axure [1]&quot;">​</a></h2><p><a href="https://www.iamxiarui.com/?p=1845" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?p=1845</a></p><p>在我的实践中，用Axure原型+注释的方式撰写，导出HTML或发布到Axshare或通过蓝湖上传的方式传达；效率最高效果最好。</p><p>Axure之于产品经理就像PhotoShop之于设计师</p><p>经典的虽然看起来没那么酷炫，但是它代表着易用性、拓展性、普适性</p><ul><li>易用性：可以找到大量教程，降低门槛快速上手</li><li>拓展性：可以获取大量素材，积累提升输出质量</li><li>普适性：可以兼容各种系统，提升工作协同效率</li></ul><p>有人用墨刀做花里胡哨的交互，文字描述寥寥，结果连异常流程都覆盖不了 有人用word写长篇大论，结果开发根本不看，还要问你每个页面怎么跳转 有人用sketch，不配合专属插件的话，很容易画成没有结构性的页面流程图。而且是否具备普适性，取决于周围与你配合的人</p><p>工具本身没有问题，有问题一定是工具人的问题。</p><p>为了让你的PRD的用户使用效果更好，汲取意见是很重要的。有的时候不要埋怨开发为什么不认真看，去问问他们喜欢看什么样的，适当调整达成统一。</p><p>Tower、禅道、tapd等团队协同工具，会导致一部分人习惯把产品的结构通过协同工具中的单个需求建立父子关系连接，在每个子需求中上传需求图片+文字描述。这种方式更适合优化已有功能，功能可以在小范围内实现闭环，但是容易使人忽略细节的调整对全局的影响。</p><p>产品经理应该把控Axure源文件的颗粒度，哪些版本/模块在一个源文件里更新，从哪个版本/模块新建文档维护；文档或文件夹之间尽量去重、解耦。在原有文件上新增或调整的部分，更显眼的做出标注，让人可以一眼看出变动的部分。</p><p>在Axure里搭建当前版本/模块最完整的产品结构，并且及时更新。要明确一个认知，协同工具是给UI、开发、测试、运营看的，目的是让他们看起来方便，可以针对单个需求设置执行人员、排期、添加bug记录等，核心价值是项目管理。而不是为了产品经理维护需求文档方便，所以在需求的撰写和管理时，不要依赖协同工具。在追溯需求问题的时候，要能做到在Axure文件里便能找到记录，而不是去翻协同工具里的需求记录。</p><p>Axure基础操作总结： <a href="https://blog.csdn.net/zcl050505/article/details/110439551" target="_blank" rel="noreferrer">https://blog.csdn.net/zcl050505/article/details/110439551</a></p>',18)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
